public class Solution {
    public List<int> Union(int[] a, int[] b) {
        var res = new List<int>();
        int i = 0, j = 0;
        while (i < a.Length && j < b.Length) {
            if (a[i] < b[j]) AddDistinct(res, a[i++]);
            else if (a[i] > b[j]) AddDistinct(res, b[j++]);
            else {
                AddDistinct(res, a[i]);
                i++;
                j++;
            }
        }
        while (i < a.Length) AddDistinct(res, a[i++]);
        while (j < b.Length) AddDistinct(res, b[j++]);
        return res;
    }

    private void AddDistinct(List<int> res, int value) {
        if (res.Count == 0 || res[res.Count - 1] != value) res.Add(value);
    }
}

