class Solution {
    int longestSubarray(int[] arr, int k) {
        int best = 0, sum = 0, left = 0;
        for (int right = 0; right < arr.length; right++) {
            sum += arr[right];
            while (sum > k && left <= right) sum -= arr[left++];
            if (sum == k) best = Math.max(best, right - left + 1);
        }
        return best;
    }
}

