class Solution {
    int[] maxSubarrayWithIndices(int[] nums) {
        int best = nums[0], cur = nums[0];
        int start = 0, end = 0, tempStart = 0;
        for (int i = 1; i < nums.length; i++) {
            if (cur + nums[i] < nums[i]) {
                cur = nums[i];
                tempStart = i;
            } else {
                cur += nums[i];
            }
            if (cur > best) {
                best = cur;
                start = tempStart;
                end = i;
            }
        }
        return new int[]{start, end};
    }
}

