class Solution {
    public void nextPermutation(int[] nums) {
        int n = nums.length;
        int pivot = n - 2;
        while (pivot >= 0 && nums[pivot] >= nums[pivot + 1]) pivot--;
        if (pivot >= 0) {
            int swapWith = n - 1;
            while (nums[swapWith] <= nums[pivot]) swapWith--;
            int temp = nums[pivot];
            nums[pivot] = nums[swapWith];
            nums[swapWith] = temp;
        }
        for (int left = pivot + 1, right = n - 1; left < right; left++, right--) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
        }
    }
}

