        List<Integer> res = new ArrayList<>();
        int max = Integer.MIN_VALUE;
        for (int i = nums.length - 1; i >= 0; i--) {
            if (nums[i] >= max) {
                res.add(nums[i]);
                max = nums[i];
            }
        }
        Collections.reverse(res);
        return res;
    }
