class Solution {
    int minDays(int[] bloomDay, int m, int k) {
        if ((long) m * k > bloomDay.length) return -1;
        int lo = 1, hi = 0;
        for (int d : bloomDay) hi = Math.max(hi, d);
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            long bouquets = 0, roses = 0;
            for (int d : bloomDay) {
                if (d <= mid) {
                    roses++;
                    if (roses == k) {
                        bouquets++;
                        roses = 0;
                    }
                } else roses = 0;
            }
            if (bouquets >= m) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

