class Solution {
    double minMaxDistance(int[] stations, int k) {
        int n = stations.length;
        double lo = 0, hi = 0;
        for (int i = 0; i < n - 1; i++) hi = Math.max(hi, stations[i + 1] - stations[i]);
        while (hi - lo > 1e-6) {
            double mid = (lo + hi) / 2;
            int used = 0;
            for (int i = 0; i < n - 1; i++)
                used += (int) Math.ceil((stations[i + 1] - stations[i]) / mid) - 1;
            if (used > k) lo = mid; else hi = mid;
        }
        return hi;
    }
}

