class Solution {
    int kthElement(int[] a, int[] b, int k) {
        return kth(a, 0, b, 0, k);
    }
    int kth(int[] a, int i, int[] b, int j, int k) {
        if (i >= a.length) return b[j + k - 1];
        if (j >= b.length) return a[i + k - 1];
        if (k == 1) return Math.min(a[i], b[j]);
        int ni = Math.min(a.length, i + k / 2) - 1;
        int nj = Math.min(b.length, j + k / 2) - 1;
        if (a[ni] <= b[nj]) return kth(a, ni + 1, b, j, k - (ni + 1 - i));
        else return kth(a, i, b, nj + 1, k - (nj + 1 - j));
    }
}

