class Solution {
    int[] findPeakGrid(int[][] m) {
        int rows = m.length, lo = 0, hi = m[0].length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int bestRow = 0;
            for (int r = 0; r < rows; r++)
                if (m[r][mid] > m[bestRow][mid]) bestRow = r;
            int left = mid > 0 ? m[bestRow][mid - 1] : -1;
            int right = mid < m[0].length - 1 ? m[bestRow][mid + 1] : -1;
            if (m[bestRow][mid] >= left && m[bestRow][mid] >= right)
                return new int[] { bestRow, mid };
            if (m[bestRow][mid] < right) lo = mid + 1;
            else hi = mid - 1;
        }
        return new int[] { -1, -1 };
    }
}

