        int lo = 1, hi = 1000000000;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2, count = 0;
            for (int r = 0; r < rows; r++) {
                int l = 0, h = cols;
                while (l < h) {
                    int b = l + (h - l) / 2;
                    if (m[r][b] <= mid) l = b + 1; else h = b;
                }
                count += l;
            }
            if (count >= need) hi = mid;
            else lo = mid + 1;
        }
        return lo;
    }
}

