class Solution {
    ListNode addOne(ListNode head) {
        head = reverse(head);
        ListNode dummy = new ListNode(0);
        dummy.next = head;
        ListNode cur = head;
        int carry = 1;
        while (cur != null) {
            int sum = cur.val + carry;
            cur.val = sum % 10;
            carry = sum / 10;
            if (carry == 0) break;
            if (cur.next == null) { cur.next = new ListNode(carry); carry = 0; }
            cur = cur.next;
        }
        return reverse(dummy.next);
    }
    ListNode reverse(ListNode h) {
        ListNode prev = null;
        while (h != null) {
            ListNode n = h.next; h.next = prev; prev = h; h = n;
        }
        return prev;
    }
}

