    int countPairs(DNode head, int x) {
        if (head == null) return 0;
        DNode last = head;
        while (last.next != null) last = last.next;
        int count = 0;
        DNode a = head, b = last;
        while (a != null && b != null && a != b && b.next != a) {
            int sum = a.val + b.val;
            if (sum == x) {
                count++;
                a = a.next;
                b = b.prev;
            } else if (sum < x) a = a.next;
            else b = b.prev;
        }
        return count;
    }
}

