                ListNode n = cur.next;
                cur.next = prev;
                prev = cur;
                cur = n;
            }
            ListNode tmp = groupPrev.next;
            groupPrev.next = kth;
            groupPrev = tmp;
        }
        return dummy.next;
    }
}

