class Solution {
    FNode flatten(FNode root) {
        if (root == null || root.next == null) return root;
        root.next = flatten(root.next);
        root = merge(root, root.next);
        root.next = null;
        return root;
    }
    FNode merge(FNode a, FNode b) {
        FNode d = new FNode(0), t = d;
        while (a != null && b != null) {
            if (a.data <= b.data) { t.bottom = a; a = a.bottom; }
            else { t.bottom = b; b = b.bottom; }
            t = t.bottom;
        }
        t.bottom = a != null ? a : b;
        return d.bottom;
    }
}

