class Solution {
    long MOD = 1_000_000_007L;
    long pow(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % MOD;
            b = b * b % MOD;
            e >>= 1;
        }
        return r;
    }
    int countGoodNumbers(long n) {
        long even = (n + 1) / 2, odd = n / 2;
        return (int) (pow(5, even) * pow(4, odd) % MOD);
    }
}

