class Solution {
    java.util.List<java.util.List<String>> solveNQueens(int n) {
        java.util.List<java.util.List<String>> res = new java.util.ArrayList<>();
        char[][] board = new char[n][n];
        for (char[] r : board) java.util.Arrays.fill(r, '.');
        bt(res, board, 0, n);
        return res;
    }
    void bt(java.util.List<java.util.List<String>> res, char[][] b, int col, int n) {
        if (col == n) {
            java.util.List<String> snap = new java.util.ArrayList<>();
            for (int i = 0; i < n; i++) snap.add(new String(b[i]));
            res.add(snap);
            return;
        }
        for (int row = 0; row < n; row++) {
            if (safe(b, row, col, n)) {
                b[row][col] = 'Q';
                bt(res, b, col + 1, n);
                b[row][col] = '.';
            }
        }
    }
    boolean safe(char[][] b, int row, int col, int n) {
        for (int i = 0; i < col; i++) if (b[row][i] == 'Q') return false;
        for (int i = row, j = col; i >= 0 && j >= 0; i--, j--) if (b[i][j] == 'Q') return false;
        for (int i = row, j = col; i < n && j >= 0; i++, j--) if (b[i][j] == 'Q') return false;
        return true;
    }
}

