class Solution {
    java.util.List<String> findPath(int[][] m, int n) {
        java.util.List<String> res = new java.util.ArrayList<>();
        if (m[0][0] == 0) return res;
        int[][] path = new int[n][n];
        dfs(m, n, 0, 0, path, new StringBuilder(), res);
        return res;
    }
    void dfs(int[][] m, int n, int i, int j, int[][] path, StringBuilder sb, java.util.List<String> res) {
        if (i == n - 1 && j == n - 1) {
            res.add(sb.toString());
            return;
        }
        if (i < 0 || j < 0 || i >= n || j >= n || m[i][j] == 0 || path[i][j] == 1) return;
        path[i][j] = 1;
        int len = sb.length();
        dfs(m, n, i, j + 1, path, sb.append('R'), res);
        dfs(m, n, i + 1, j, path, sb.append('D'), res);
        dfs(m, n, i, j - 1, path, sb.append('L'), res);
        dfs(m, n, i - 1, j, path, sb.append('U'), res);
        sb.setLength(len);
        path[i][j] = 0;
    }
}

