class Solution {
    Boolean[] memo;
    boolean wordBreak(String s, java.util.List<String> dict) {
        memo = new Boolean[s.length()];
        return can(s, dict, 0);
    }
    boolean can(String s, java.util.List<String> dict, int start) {
        if (start == s.length()) return true;
        if (memo[start] != null) return memo[start];
        for (String w : dict) {
            int len = w.length();
            if (start + len <= s.length() && s.startsWith(w, start)
                && can(s, dict, start + len)) {
                memo[start] = true;
                return true;
            }
        }
        memo[start] = false;
        return false;
    }
}

