class Solution {
    boolean graphColoring(int[][] graph, int[] colors, int m, int node) {
        int n = colors.length;
        if (node == n) return true;
        for (int c = 1; c <= m; c++) {
            if (isSafe(graph, colors, node, c)) {
                colors[node] = c;
                if (graphColoring(graph, colors, m, node + 1)) return true;
                colors[node] = 0;
            }
        }
        return false;
    }
