class Solution {
    boolean solveSudoku(char[][] b) {
        for (int i = 0; i < 9; i++)
            for (int j = 0; j < 9; j++) {
                if (b[i][j] == '.') {
                    for (char c = '1'; c <= '9'; c++) {
                        if (valid(b, i, j, c)) {
                            b[i][j] = c;
                            if (solveSudoku(b)) return true;
                            b[i][j] = '.';
                        }
                    }
                    return false;
                }
            }
        return true;
    }
    boolean valid(char[][] b, int r, int c, char v) {
        for (int i = 0; i < 9; i++) {
            if (b[r][i] == v || b[i][c] == v) return false;
            int br = 3 * (r / 3) + i / 3, bc = 3 * (c / 3) + i % 3;
            if (b[br][bc] == v) return false;
        }
        return true;
    }
}

