class Solution {
    java.util.List<String> addOperators(String num, int target) {
        java.util.List<String> res = new java.util.ArrayList<>();
        bt(res, new StringBuilder(), num, 0, 0, 0, target);
        return res;
    }
    void bt(java.util.List<String> res, StringBuilder path, String num, int idx, long value, long prev, long target) {
        if (idx == num.length()) {
            if (value == target) res.add(path.toString());
            return;
        }
        for (int i = idx; i < num.length(); i++) {
            if (i != idx && num.charAt(idx) == '0') break;
            long cur = Long.parseLong(num.substring(idx, i + 1));
            int len = path.length();
            if (idx == 0) {
                path.append(cur);
                bt(res, path, num, i + 1, cur, cur, target);
                path.setLength(len);
            } else {
                path.append('+').append(cur);
                bt(res, path, num, i + 1, value + cur, cur, target);
                path.setLength(len);
                path.append('-').append(cur);
                bt(res, path, num, i + 1, value - cur, -cur, target);
                path.setLength(len);
                path.append('*').append(cur);
                bt(res, path, num, i + 1, (value - prev) + prev * cur, prev * cur, target);
                path.setLength(len);
            }
        }
    }
}

