class Solution {
    int divide(int dividend, int divisor) {
        if (dividend == Integer.MIN_VALUE && divisor == -1) return Integer.MAX_VALUE;
        long a = Math.abs((long) dividend), b = Math.abs((long) divisor);
        int sign = ((long) dividend ^ (long) divisor) >= 0 ? 1 : -1;
        int q = 0;
        while (a >= b) {
            long t = b, p = 1;
            while (a >= (t << 1)) { t <<= 1; p <<= 1; }
            a -= t;
            q += (int) p;
        }
        return sign * q;
    }
}

