class Solution {
    String infixToPostfix(String s) {
        StringBuilder out = new StringBuilder();
        java.util.Deque<Character> st = new java.util.ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (Character.isLetterOrDigit(c)) out.append(c);
            else if (c == '(') st.push(c);
            else if (c == ')') { while (!st.isEmpty() && st.peek() != '(') out.append(st.pop()); st.pop(); }
            else { while (!st.isEmpty() && prec(st.peek()) >= prec(c)) out.append(st.pop()); st.push(c); }
        }
        while (!st.isEmpty()) out.append(st.pop());
        return out.toString();
    }
    int prec(char op) { switch (op) { case '+': case '-': return 1; case '*': case '/': return 2; case '^': return 3; default: return -1; } }
}

