            else if (c == '(') st.Push(c);
            else if (c == ')') { while (st.Count > 0 && st.Peek() != '(') outp.Append(st.Pop()); st.Pop(); }
            else { while (st.Count > 0 && Prec(st.Peek()) > Prec(c)) outp.Append(st.Pop()); st.Push(c); }
        }
        while (st.Count > 0) outp.Append(st.Pop());
        char[] res = outp.ToString().ToCharArray();
        System.Array.Reverse(res);
        return new string(res);
    }
    int Prec(char op) => op switch { '+' or '-' => 1, '*' or '/' => 2, '^' => 3, _ => -1 };
}

