class Solution {
    static class LRUCache {
        int cap;
        java.util.Map<Integer, Node> map;
        Node head, tail;
        static class Node { int k, v; Node prev, next; Node(int k, int v){this.k=k;this.v=v;} }
        LRUCache(int capacity) {
            cap = capacity; map = new java.util.HashMap<>();
            head = new Node(0,0); tail = new Node(0,0);
            head.next = tail; tail.prev = head;
        }
        int get(int key) {
            if (!map.containsKey(key)) return -1;
            Node n = map.get(key); remove(n); addFront(n);
            return n.v;
        }
        void put(int key, int value) {
            if (map.containsKey(key)) { Node old = map.get(key); old.v = value; remove(old); addFront(old); return; }
            Node n = new Node(key, value);
            if (map.size() == cap) { Node lru = tail.prev; remove(lru); map.remove(lru.k); }
            addFront(n); map.put(key, n);
        }
        void remove(Node n) { n.prev.next = n.next; n.next.prev = n.prev; }
        void addFront(Node n) { n.next = head.next; n.prev = head; head.next.prev = n; head.next = n; }
    }
}

