public class LRUCache {
    class Node { public int K, V; public Node Prev, Next; }
    int cap; Dictionary<int, Node> map = new(); Node head, tail;
    public LRUCache(int capacity) {
        cap = capacity; head = new Node(); tail = new Node();
        head.Next = tail; tail.Prev = head;
    }
    public int Get(int key) {
        if (!map.ContainsKey(key)) return -1;
        var n = map[key]; Remove(n); AddFront(n); return n.V;
    }
    public void Put(int key, int value) {
        if (map.ContainsKey(key)) { var old = map[key]; old.V = value; Remove(old); AddFront(old); return; }
        var n = new Node { K = key, V = value };
        if (map.Count == cap) { var lru = tail.Prev; Remove(lru); map.Remove(lru.K); }
        AddFront(n); map[key] = n;
    }
    void Remove(Node n) { n.Prev.Next = n.Next; n.Next.Prev = n.Prev; }
    void AddFront(Node n) { n.Next = head.Next; n.Prev = head; head.Next.Prev = n; head.Next = n; }
}

