class Solution {
    static class LFUCache {
        int cap, minFreq;
        java.util.Map<Integer, Node> keyMap;
        java.util.Map<Integer, java.util.LinkedHashSet<Integer>> freqMap;
        static class Node { int k, v, freq; Node(int k, int v){this.k=k;this.v=v;freq=1;} }
        LFUCache(int capacity) { cap=capacity; minFreq=0; keyMap=new java.util.HashMap<>(); freqMap=new java.util.HashMap<>(); }
        int get(int key) {
            if (!keyMap.containsKey(key)) return -1;
            Node n = keyMap.get(key); touch(n); return n.v;
        }
        void put(int key, int value) {
            if (cap == 0) return;
            if (keyMap.containsKey(key)) { keyMap.get(key).v = value; touch(keyMap.get(key)); return; }
            if (keyMap.size() == cap) {
                var set = freqMap.get(minFreq);
                int evict = set.iterator().next(); set.remove(evict); keyMap.remove(evict);
            }
            Node n = new Node(key, value); keyMap.put(key, n);
            freqMap.computeIfAbsent(1, x -> new java.util.LinkedHashSet<>()).add(key);
            minFreq = 1;
        }
        void touch(Node n) {
            int f = n.freq; n.freq++;
            freqMap.get(f).remove(n.k);
            if (f == minFreq && freqMap.get(f).isEmpty()) minFreq++;
            freqMap.computeIfAbsent(n.freq, x -> new java.util.LinkedHashSet<>()).add(n.k);
        }
    }
}

code.csharp:
public class LFUCache {
    class Node { public int K, V, Freq; public Node(int k, int v) { K=k; V=v; Freq=1; } }
    int cap, minFreq; Dictionary<int, Node> keyMap = new(); Dictionary<int, LinkedHashSet<int>> freqMap = new();
    public LFUCache(int capacity) { cap = capacity; }
    public int Get(int key) { if (!keyMap.ContainsKey(key)) return -1; var n = keyMap[key]; Touch(n); return n.V; }
    public void Put(int key, int value) {
        if (cap == 0) return;
        if (keyMap.ContainsKey(key)) { keyMap[key].V = value; Touch(keyMap[key]); return; }
        if (keyMap.Count == cap) {
            var set = freqMap[minFreq]; int evict = set.First(); set.Remove(evict); keyMap.Remove(evict);
        }
        var node = new Node(key, value); keyMap[key] = node;
        if (!freqMap.ContainsKey(1)) freqMap[1] = new LinkedHashSet<int>();
        freqMap[1].Add(key); minFreq = 1;
    }
    void Touch(Node n) {
        int f = n.Freq; n.Freq++;
        freqMap[f].Remove(n.K);
        if (f == minFreq && freqMap[f].Count == 0) minFreq++;
        if (!freqMap.ContainsKey(n.Freq)) freqMap[n.Freq] = new LinkedHashSet<int>();
        freqMap[n.Freq].Add(n.K);
    }
}

