class Solution {
    int numSubarraysWithSum(int[] nums, int goal) {
        int res = 0, prefix = 0;
        java.util.Map<Integer, Integer> cnt = new java.util.HashMap<>();
        cnt.put(0, 1);
        for (int x : nums) {
            prefix += x;
            res += cnt.getOrDefault(prefix - goal, 0);
            cnt.merge(prefix, 1, Integer::sum);
        }
        return res;
    }
