class Solution {
    int maxScore(int[] cardPoints, int k) {
        int n = cardPoints.length, total = 0;
        for (int x : cardPoints) total += x;
        int win = n - k, curSum = 0, minSum = 0;
        for (int i = 0; i < win; i++) curSum += cardPoints[i];
        minSum = curSum;
        for (int i = win; i < n; i++) {
            curSum += cardPoints[i] - cardPoints[i - win];
            minSum = Math.min(minSum, curSum);
        }
        return total - minSum;
    }
}

