class Solution {
    String minWindow(String s, String t) {
        int m = t.length(), n = s.length();
        int best = Integer.MAX_VALUE, start = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == t.charAt(j)) j++;
            if (j == m) {
                int end = i + 1;
                j--;
                while (j >= 0) { i--; if (s.charAt(i) == t.charAt(j)) j--; }
                i++; j++;
                if (end - i < best) { best = end - i; start = i; }
            }
        }
        return best == Integer.MAX_VALUE ? "" : s.substring(start, start + best);
    }
}

