class Solution {
    static class MinHeap {
        int[] h = new int[128]; int sz;
        void insert(int v) {
            if (sz == h.length) h = java.util.Arrays.copyOf(h, sz * 2);
            h[sz] = v; siftUp(sz); sz++;
        }
        int extractMin() {
            int min = h[0]; h[0] = h[--sz]; siftDown(0); return min;
        }
        void siftUp(int i) { while (i > 0 && h[i] < h[(i-1)/2]) { swap(i, (i-1)/2); i = (i-1)/2; } }
        void siftDown(int i) {
            while (true) {
                int s = i, l = 2*i+1, r = 2*i+2;
                if (l < sz && h[l] < h[s]) s = l;
                if (r < sz && h[r] < h[s]) s = r;
                if (s == i) break; swap(i, s); i = s;
            }
        }
        void swap(int a, int b) { int t = h[a]; h[a] = h[b]; h[b] = t; }
        int size() { return sz; }
    }
}

code.csharp:
public class MinHeap {
    int[] h = new int[128]; int sz;
    public void Insert(int v) { if (sz == h.Length) System.Array.Resize(ref h, sz * 2); h[sz] = v; SiftUp(sz); sz++; }
    public int ExtractMin() { int min = h[0]; h[0] = h[--sz]; SiftDown(0); return min; }
    void SiftUp(int i) { while (i > 0 && h[i] < h[(i-1)/2]) { Swap(i, (i-1)/2); i = (i-1)/2; } }
    void SiftDown(int i) {
        while (true) {
            int s = i, l = 2*i+1, r = 2*i+2;
            if (l < sz && h[l] < h[s]) s = l;
            if (r < sz && h[r] < h[s]) s = r;
            if (s == i) break; Swap(i, s); i = s;
        }
    }
    void Swap(int a, int b) { (h[a], h[b]) = (h[b], h[a]); }
    public int Size() => sz;
}

