class Solution {
    int[] minToMaxHeap(int[] h) {
        int n = h.length;
        for (int i = n / 2 - 1; i >= 0; i--) siftDownMax(h, i, n);
        return h;
    }
    void siftDownMax(int[] h, int i, int n) {
        while (true) {
            int s = i, l = 2*i+1, r = 2*i+2;
            if (l < n && h[l] > h[s]) s = l;
            if (r < n && h[r] > h[s]) s = r;
            if (s == i) break;
            int t = h[i]; h[i] = h[s]; h[s] = t; i = s;
        }
    }
}

