public class Solution {
    public int[] MinToMaxHeap(int[] h) {
        int n = h.Length;
        for (int i = n / 2 - 1; i >= 0; i--) SiftDownMax(h, i, n);
        return h;
    }
    void SiftDownMax(int[] h, int i, int n) {
        while (true) {
            int s = i, l = 2*i+1, r = 2*i+2;
            if (l < n && h[l] > h[s]) s = l;
            if (r < n && h[r] > h[s]) s = r;
            if (s == i) break;
            (h[i], h[s]) = (h[s], h[i]); i = s;
        }
    }
}

