public class Solution {
    public ListNode MergeKLists(ListNode[] lists) {
        var pq = new PriorityQueue<ListNode, int>();
        foreach (var n in lists) if (n != null) pq.Enqueue(n, n.val);
        var dummy = new ListNode(0); var cur = dummy;
        while (pq.Count > 0) {
            var min = pq.Dequeue(); cur.next = min; cur = min;
            if (min.next != null) pq.Enqueue(min.next, min.next.val);
        }
        return dummy.next;
    }
}

