class Solution {
    boolean isNStraightHand(int[] hand, int gs) {
        if (hand.length % gs != 0) return false;
        java.util.TreeMap<Integer, Integer> cnt = new java.util.TreeMap<>();
        for (int x : hand) cnt.merge(x, 1, Integer::sum);
        while (!cnt.isEmpty()) {
            int start = cnt.firstKey();
            for (int i = 0; i < gs; i++) {
                int k = start + i;
                if (!cnt.containsKey(k)) return false;
                if (cnt.get(k) == 1) cnt.remove(k); else cnt.put(k, cnt.get(k) - 1);
            }
        }
        return true;
    }
}

