public class Solution {
    public bool IsNStraightHand(int[] hand, int gs) {
        if (hand.Length % gs != 0) return false;
        var cnt = new SortedDictionary<int, int>();
        foreach (int x in hand) { cnt.TryGetValue(x, out int v); cnt[x] = v + 1; }
        while (cnt.Count > 0) {
            int start = 0; bool first = true;
            foreach (int k in cnt.Keys) { start = k; first = false; break; }
            for (int i = 0; i < gs; i++) {
                int k = start + i;
                if (!cnt.ContainsKey(k)) return false;
                if (cnt[k] == 1) cnt.Remove(k); else cnt[k]--;
            }
        }
        return true;
    }
}

