            java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> a[1] - b[1]);
            java.util.Set<Integer> users = new java.util.HashSet<>(); users.add(userId);
            if (follows.containsKey(userId)) users.addAll(follows.get(userId));
            for (int u : users) {
                if (!tweets.containsKey(u)) continue;
                for (int[] t : tweets.get(u)) { pq.offer(t); if (pq.size() > 10) pq.poll(); }
            }
            java.util.List<Integer> res = new java.util.ArrayList<>();
            while (!pq.isEmpty()) res.add(pq.poll()[0]);
            java.util.Collections.reverse(res);
