class Solution {
    int[] maxCombinations(int[] A, int[] B, int k) {
        int n = A.length;
        java.util.Arrays.sort(A); java.util.Arrays.sort(B);
        java.util.PriorityQueue<int[]> pq = new java.util.PriorityQueue<>((a, b) -> (A[b[1]] + B[b[2]]) - (A[a[1]] + B[a[2]]));
        java.util.HashSet<String> vis = new java.util.HashSet<>();
        int[] res = new int[k];
        for (int i = n - 1; i >= 0; i--) { pq.offer(new int[]{A[i] + B[n-1], i, n - 1}); vis.add(i + "," + (n-1)); }
        for (int t = 0; t < k; t++) {
            int[] top = pq.poll();
            res[t] = top[0];
            int i = top[1], j = top[2];
            if (j > 0 && !vis.contains(i + "," + (j-1))) { pq.offer(new int[]{A[i]+B[j-1], i, j-1}); vis.add(i + "," + (j-1)); }
            if (i > 0 && !vis.contains((i-1) + "," + j)) { pq.offer(new int[]{A[i-1]+B[j], i-1, j}); vis.add((i-1) + "," + j); }
        }
        return res;
    }
}

