public class Solution {
    public int[] MaxCombinations(int[] A, int[] B, int k) {
        int n = A.Length;
        System.Array.Sort(A); System.Array.Sort(B);
        var pq = new PriorityQueue<(int sum, int i, int j), int>();
        var vis = new HashSet<string>();
        int[] res = new int[k];
        for (int i = n - 1; i >= 0; i--) { pq.Enqueue((A[i]+B[n-1], i, n-1), -(A[i]+B[n-1])); vis.Add($"{i},{n-1}"); }
        for (int t = 0; t < k; t++) {
            var top = pq.Dequeue(); res[t] = top.sum;
            int i = top.i, j = top.j;
            if (j > 0 && vis.Add($"{i},{j-1}")) pq.Enqueue((A[i]+B[j-1], i, j-1), -(A[i]+B[j-1]));
            if (i > 0 && vis.Add($"{i-1},{j}")) pq.Enqueue((A[i-1]+B[j], i-1, j), -(A[i-1]+B[j]));
        }
        return res;
    }
}

