class Solution {
    int[] topKFrequent(int[] nums, int k) {
        java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
        for (int x : nums) freq.merge(x, 1, Integer::sum);
        java.util.List<Integer>[] bucket = new java.util.List[nums.length + 1];
        for (var e : freq.entrySet()) { int f = e.getValue(); if (bucket[f] == null) bucket[f] = new java.util.ArrayList<>(); bucket[f].add(e.getKey()); }
        int[] res = new int[k]; int idx = 0;
        for (int i = bucket.length - 1; i >= 0 && idx < k; i--)
            if (bucket[i] != null) for (int v : bucket[i]) { if (idx >= k) break; res[idx++] = v; }
        return res;
    }
}

