class Solution {
    double fractionalKnapsack(int[] val, int[] wt, int cap) {
        int n = val.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> Double.compare((double) val[b] / wt[b], (double) val[a] / wt[a]));
        double res = 0;
        for (int i : idx) {
            if (cap >= wt[i]) { res += val[i]; cap -= wt[i]; }
            else { res += (double) val[i] * cap / wt[i]; break; }
        }
        return res;
    }
}

