class Solution {
    int[] jobScheduling(int[] deadline, int[] profit, int n) {
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) -> profit[b] - profit[a]);
        boolean[] slot = new boolean[n + 1];
        int cnt = 0, maxProfit = 0;
        for (int i : idx) {
            for (int j = Math.min(deadline[i], n); j >= 1; j--) {
                if (!slot[j]) { slot[j] = true; cnt += 1; maxProfit += profit[i]; break; }
            }
        }
        return new int[]{cnt, maxProfit};
    }
}

