class Solution {
    int pageFaults(int[] pages, int n, int cap) {
        java.util.LinkedHashSet<Integer> mem = new java.util.LinkedHashSet<>();
        int faults = 0;
        for (int i = 0; i < n; i++) {
            if (mem.contains(pages[i])) { mem.remove(pages[i]); mem.add(pages[i]); continue; }
            faults++;
            if (mem.size() >= cap) mem.remove(mem.iterator().next());
            mem.add(pages[i]);
        }
        return faults;
    }
}

