        int faults = 0;
        for (int i = 0; i < n; i++) {
            int idx = mem.IndexOf(pages[i]);
            if (idx >= 0) { mem.RemoveAt(idx); mem.Add(pages[i]); continue; }
            faults++;
            if (mem.Count >= cap) mem.RemoveAt(0);
            mem.Add(pages[i]);
        }
        return faults;
    }
}

