class Solution {
    public void allTraversals(TreeNode root, List<Integer> pre, List<Integer> in, List<Integer> post) {
        if (root == null) return;

        Deque<Pair> stack = new ArrayDeque<>();
        stack.push(new Pair(root, 1));

        while (!stack.isEmpty()) {
            Pair current = stack.peek();

            if (current.state == 1) {
                // First visit → preorder.
                pre.add(current.node.val);
                current.state++;

                if (current.node.left != null) stack.push(new Pair(current.node.left, 1));
            } else if (current.state == 2) {
                // Returning from the left subtree → inorder.
                in.add(current.node.val);
                current.state++;

                if (current.node.right != null) stack.push(new Pair(current.node.right, 1));
            } else {
                // Both subtrees finished → postorder.
                post.add(current.node.val);
                stack.pop();
            }
        }
    }

    static class Pair {
        TreeNode node;
        int state;

        Pair(TreeNode node, int state) {
            this.node = node;
            this.state = state;
        }
    }
}

