class Solution {
    public int maxPathSum(TreeNode root) {
        int[] answer = {Integer.MIN_VALUE};
        maxGain(root, answer);
        return answer[0];
    }

    private int maxGain(TreeNode root, int[] answer) {
        if (root == null) return 0;

        // A negative branch can only hurt the path.
        int left = Math.max(0, maxGain(root.left, answer));
        int right = Math.max(0, maxGain(root.right, answer));

        // Best path that passes through the current node.
        int pathThroughNode = root.val + left + right;
        answer[0] = Math.max(answer[0], pathThroughNode);

        // The parent can continue through only one side.
        return root.val + Math.max(left, right);
    }
}

