class Solution {
    public List<Integer> boundary(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        // The root is added once, unless it is also a leaf.
        if (!isLeaf(root)) result.add(root.val);

        addLeftBoundary(root.left, result);
        addLeaves(root, result);
        addRightBoundary(root.right, result);

        return result;
    }

    private void addLeftBoundary(TreeNode root, List<Integer> result) {
        while (root != null) {
            if (!isLeaf(root)) result.add(root.val);

            // Prefer the left child, fall back to the right child.
            root = root.left != null ? root.left : root.right;
        }
    }

    private void addRightBoundary(TreeNode root, List<Integer> result) {
        List<Integer> temp = new ArrayList<>();

        while (root != null) {
            if (!isLeaf(root)) temp.add(root.val);

            root = root.right != null ? root.right : root.left;
        }

        // The right boundary is collected bottom-up, so reverse it.
        for (int i = temp.size() - 1; i >= 0; i--) result.add(temp.get(i));
    }

    private void addLeaves(TreeNode root, List<Integer> result) {
        if (root == null) return;

        if (isLeaf(root)) {
            result.add(root.val);
            return;
        }

        addLeaves(root.left, result);
        addLeaves(root.right, result);
    }

    private boolean isLeaf(TreeNode root) {
        return root.left == null && root.right == null;
    }
}

