    private void AddRightBoundary(TreeNode root, List<int> result) {
        List<int> temp = new List<int>();

        while (root != null) {
            if (!IsLeaf(root)) temp.Add(root.Val);

            root = root.Right != null ? root.Right : root.Left;
        }

        // The right boundary is collected bottom-up, so reverse it.
        for (int i = temp.Count - 1; i >= 0; i--) result.Add(temp[i]);
