    private void AddLeaves(TreeNode root, List<int> result) {
        if (root == null) return;

        if (IsLeaf(root)) {
            result.Add(root.Val);
            return;
        }

        AddLeaves(root.Left, result);
        AddLeaves(root.Right, result);
    }

    private bool IsLeaf(TreeNode root) {
        return root.Left == null && root.Right == null;
    }
