class Solution {
    public List<List<Integer>> verticalTraversalSort(TreeNode root) {
        List<int[]> entries = new ArrayList<>();
        dfs(root, 0, 0, entries);

        // Sort by horizontal distance, then level, then value.
        entries.sort((a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0])
                       : a[1] != b[1] ? Integer.compare(a[1], b[1])
                       : Integer.compare(a[2], b[2]));

        List<List<Integer>> result = new ArrayList<>();
        List<Integer> column = null;
        int currentHd = 0;

        for (int[] entry : entries) {
            if (column == null || entry[0] != currentHd) {
                column = new ArrayList<>();
                result.add(column);
                currentHd = entry[0];
            }
            column.add(entry[2]);
        }

        return result;
    }

    private void dfs(TreeNode node, int hd, int level, List<int[]> entries) {
        if (node == null) return;

        entries.add(new int[] {hd, level, node.val});

        dfs(node.left, hd - 1, level + 1, entries);
        dfs(node.right, hd + 1, level + 1, entries);
    }
}

