class Solution {
    public List<List<Integer>> verticalTraversal(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) return result;

        // Horizontal distance → level → sorted values.
        TreeMap<Integer, TreeMap<Integer, PriorityQueue<Integer>>> map = new TreeMap<>();
        Queue<NodeInfo> queue = new LinkedList<>();
        queue.offer(new NodeInfo(root, 0, 0));

        while (!queue.isEmpty()) {
            NodeInfo current = queue.poll();

            map.computeIfAbsent(current.hd, x -> new TreeMap<>())
               .computeIfAbsent(current.level, x -> new PriorityQueue<>())
               .offer(current.node.val);

            if (current.node.left != null) queue.offer(new NodeInfo(current.node.left, current.hd - 1, current.level + 1));
            if (current.node.right != null) queue.offer(new NodeInfo(current.node.right, current.hd + 1, current.level + 1));
        }

        for (TreeMap<Integer, PriorityQueue<Integer>> levels : map.values()) {
            List<Integer> column = new ArrayList<>();
            for (PriorityQueue<Integer> heap : levels.values()) {
                while (!heap.isEmpty()) column.add(heap.poll());
            }
            result.add(column);
        }

        return result;
    }

    static class NodeInfo {
        TreeNode node;
        int hd;
        int level;

        NodeInfo(TreeNode node, int hd, int level) {
            this.node = node;
            this.hd = hd;
            this.level = level;
        }
    }
}

