    public List<Integer> topView(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        if (root == null) return result;

        TreeMap<Integer, Integer> map = new TreeMap<>();
        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0));

        while (!queue.isEmpty()) {
            Pair current = queue.poll();

            // The first node at each horizontal distance stays visible.
            map.putIfAbsent(current.hd, current.node.val);

            if (current.node.left != null) queue.offer(new Pair(current.node.left, current.hd - 1));
            if (current.node.right != null) queue.offer(new Pair(current.node.right, current.hd + 1));
        }

        result.addAll(map.values());
        return result;
    }

    static class Pair {
        TreeNode node;
        int hd;

        Pair(TreeNode node, int hd) {
            this.node = node;
            this.hd = hd;
        }
    }
}

