class Solution {
    public List<Integer> rightViewDfs(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        visitRightFirst(root, 0, result);
        return result;
    }

    public List<Integer> leftViewDfs(TreeNode root) {
        List<Integer> result = new ArrayList<>();
        visitLeftFirst(root, 0, result);
        return result;
    }

    private void visitRightFirst(TreeNode node, int depth, List<Integer> result) {
        if (node == null) return;

        // The first node reached at each depth is the visible one.
        if (depth == result.size()) result.add(node.val);

        visitRightFirst(node.right, depth + 1, result);
        visitRightFirst(node.left, depth + 1, result);
    }

    private void visitLeftFirst(TreeNode node, int depth, List<Integer> result) {
        if (node == null) return;

        if (depth == result.size()) result.add(node.val);

        visitLeftFirst(node.left, depth + 1, result);
        visitLeftFirst(node.right, depth + 1, result);
    }
}

