class Solution {
    public List<List<Integer>> rootToLeafPathsBrute(TreeNode root) {
        List<List<Integer>> result = new ArrayList<>();
        List<TreeNode> leaves = new ArrayList<>();
        collectLeaves(root, leaves);

        for (TreeNode leaf : leaves) {
            List<TreeNode> path = new ArrayList<>();
            findPath(root, leaf, path);

            List<Integer> values = new ArrayList<>();
            for (TreeNode node : path) values.add(node.val);
            result.add(values);
        }
        return result;
    }

    private void collectLeaves(TreeNode root, List<TreeNode> leaves) {
        if (root == null) return;
        if (root.left == null && root.right == null) {
            leaves.add(root);
            return;
        }
        collectLeaves(root.left, leaves);
        collectLeaves(root.right, leaves);
    }

    private boolean findPath(TreeNode root, TreeNode target, List<TreeNode> path) {
        if (root == null) return false;

        path.add(root);
        if (root == target) return true;

        if (findPath(root.left, target, path) || findPath(root.right, target, path)) return true;

        path.remove(path.size() - 1);
        return false;
    }
}

