class Solution {
    public int widthOfBinaryTreeDfs(TreeNode root) {
        Map<Integer, Long> first = new HashMap<>();
        Map<Integer, Long> last = new HashMap<>();
        dfs(root, 0, 0L, first, last);

        long maxWidth = 0;
        for (int level : first.keySet()) {
            maxWidth = Math.max(maxWidth, last.get(level) - first.get(level) + 1);
        }
        return (int) maxWidth;
    }

    private void dfs(TreeNode node, int level, long index, Map<Integer, Long> first, Map<Integer, Long> last) {
        if (node == null) return;

        first.putIfAbsent(level, index);
        last.put(level, index);

        // Heap-style child indices.
        dfs(node.left, level + 1, 2 * index + 1, first, last);
        dfs(node.right, level + 1, 2 * index + 2, first, last);
    }
}

