class Solution {
    public int widthOfBinaryTree(TreeNode root) {
        if (root == null) return 0;

        Queue<Pair> queue = new LinkedList<>();
        queue.offer(new Pair(root, 0L));

        long maxWidth = 0;

        while (!queue.isEmpty()) {
            int size = queue.size();

            long first = queue.peek().index;
            long last = first;

            for (int i = 0; i < size; i++) {
                Pair current = queue.poll();

                // Normalize the index to prevent overflow.
                long index = current.index - first;
                last = index;

                if (current.node.left != null) queue.offer(new Pair(current.node.left, 2 * index + 1));
                if (current.node.right != null) queue.offer(new Pair(current.node.right, 2 * index + 2));
            }

            maxWidth = Math.max(maxWidth, last + 1);
        }

        return (int) maxWidth;
    }

    static class Pair {
        TreeNode node;
        long index;

        Pair(TreeNode node, long index) {
            this.node = node;
            this.index = index;
        }
    }
}

