class Solution {
    public boolean checkChildrenSumIterative(TreeNode root) {
        if (root == null) return true;

        Queue<TreeNode> queue = new LinkedList<>();
        queue.offer(root);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();

            // Leaf nodes trivially satisfy the property.
            if (node.left == null && node.right == null) continue;

            int sum = 0;
            if (node.left != null) {
                sum += node.left.val;
                queue.offer(node.left);
            }
            if (node.right != null) {
                sum += node.right.val;
                queue.offer(node.right);
            }

            if (node.val != sum) return false;
        }

        return true;
    }
}

