    public List<Integer> distanceKBrute(TreeNode root, TreeNode target, int k) {
        List<Integer> result = new ArrayList<>();

        List<TreeNode> targetPath = new ArrayList<>();
        findPath(root, target, targetPath);

        collect(root, root, targetPath, k, result);
        return result;
