    private void collect(TreeNode node, TreeNode root, List<TreeNode> targetPath, int k, List<Integer> result) {
        if (node == null) return;

        List<TreeNode> nodePath = new ArrayList<>();
        findPath(root, node, nodePath);

        if (distance(nodePath, targetPath) == k) result.add(node.val);

        collect(node.left, root, targetPath, k, result);
        collect(node.right, root, targetPath, k, result);
    }

    private int distance(List<TreeNode> a, List<TreeNode> b) {
        int common = 0;
        while (common < a.size() && common < b.size() && a.get(common) == b.get(common)) common++;
        return a.size() + b.size() - 2 * common;
    }

    private boolean findPath(TreeNode root, TreeNode target, List<TreeNode> path) {
        if (root == null) return false;

        path.add(root);
        if (root == target) return true;

        if (findPath(root.left, target, path) || findPath(root.right, target, path)) return true;

        path.remove(path.size() - 1);
        return false;
    }
