    public List<int> DistanceK(TreeNode root, TreeNode target, int k) {
        Dictionary<TreeNode, TreeNode> parent = new Dictionary<TreeNode, TreeNode>();
        BuildParents(root, parent);

        Queue<TreeNode> queue = new Queue<TreeNode>();
        HashSet<TreeNode> visited = new HashSet<TreeNode>();
        queue.Enqueue(target);
        visited.Add(target);

        int distance = 0;

        while (queue.Count > 0) {
            if (distance == k) {
                List<int> result = new List<int>();
                foreach (TreeNode node in queue) result.Add(node.Val);
                return result;
            }

            int size = queue.Count;

            for (int i = 0; i < size; i++) {
                TreeNode current = queue.Dequeue();

                if (current.Left != null && visited.Add(current.Left)) queue.Enqueue(current.Left);
                if (current.Right != null && visited.Add(current.Right)) queue.Enqueue(current.Right);

                if (parent.ContainsKey(current)) {
                    TreeNode p = parent[current];
                    if (visited.Add(p)) queue.Enqueue(p);
                }
            }

            distance++;
        }

        return new List<int>();
    }

    private void BuildParents(TreeNode root, Dictionary<TreeNode, TreeNode> parent) {
        Queue<TreeNode> queue = new Queue<TreeNode>();
        queue.Enqueue(root);

        while (queue.Count > 0) {
            TreeNode current = queue.Dequeue();

            if (current.Left != null) {
                parent[current.Left] = current;
                queue.Enqueue(current.Left);
            }

            if (current.Right != null) {
                parent[current.Right] = current;
                queue.Enqueue(current.Right);
            }
        }
    }
