                    burnedNewNode = true;
                }

                if (current.right != null && visited.add(current.right)) {
                    queue.offer(current.right);
                    burnedNewNode = true;
                }

                TreeNode p = parent.get(current);
                if (p != null && visited.add(p)) {
                    queue.offer(p);
                    burnedNewNode = true;
                }
            }

            if (burnedNewNode) time++;
        }

        return time;
