class Solution {
    public int burnTreeNoParentMap(TreeNode root, int target) {
        List<TreeNode> path = new ArrayList<>();
        findPath(root, target, path);

        int time = 0;

        for (int i = 0; i < path.size(); i++) {
            TreeNode node = path.get(i);
            TreeNode pathChild = i + 1 < path.size() ? path.get(i + 1) : null;

            // Time for the fire to travel from the target up to this path node.
            int arrival = path.size() - 1 - i;

            // Deepest off-path subtree hanging from this node.
            int offPathDepth = offPathDepth(node, pathChild);

            time = Math.max(time, arrival + offPathDepth);
        }

        return time;
    }

    private boolean findPath(TreeNode root, int target, List<TreeNode> path) {
        if (root == null) return false;

        path.add(root);
        if (root.val == target) return true;

        if (findPath(root.left, target, path) || findPath(root.right, target, path)) return true;

        path.remove(path.size() - 1);
        return false;
    }

    private int offPathDepth(TreeNode node, TreeNode blocked) {
        if (node == null) return -1;

        int best = -1;
        if (node.left != blocked) best = Math.max(best, offPathDepth(node.left, blocked));
        if (node.right != blocked) best = Math.max(best, offPathDepth(node.right, blocked));

        // The node itself counts as depth 0.
        return best + 1;
    }
}

