class Solution {
    public TreeNode buildTreeBrute(int[] preorder, int[] inorder) {
        int[] preIndex = {0};
        return build(preorder, inorder, 0, inorder.length - 1, preIndex);
    }

    private TreeNode build(int[] preorder, int[] inorder, int left, int right, int[] preIndex) {
        if (left > right) return null;

        int value = preorder[preIndex[0]++];

        // Linear search for the root inside the inorder window.
        int mid = left;
        while (inorder[mid] != value) mid++;

        TreeNode root = new TreeNode(value);
        root.left = build(preorder, inorder, left, mid - 1, preIndex);
        root.right = build(preorder, inorder, mid + 1, right, preIndex);
        return root;
    }
}

