public class Solution {
    public TreeNode BuildTreeBrute(int[] preorder, int[] inorder) {
        int preIndex = 0;
        return Build(preorder, inorder, 0, inorder.Length - 1, ref preIndex);
    }

    private TreeNode Build(int[] preorder, int[] inorder, int left, int right, ref int preIndex) {
        if (left > right) return null;

        int value = preorder[preIndex++];

        // Linear search for the root inside the inorder window.
        int mid = left;
        while (inorder[mid] != value) mid++;

