class Solution {
    public TreeNode buildTreeBrute(int[] inorder, int[] postorder) {
        int[] postIndex = {postorder.length - 1};
        return build(inorder, postorder, 0, inorder.length - 1, postIndex);
    }

    private TreeNode build(int[] inorder, int[] postorder, int left, int right, int[] postIndex) {
        if (left > right) return null;

        int value = postorder[postIndex[0]--];

        // Linear search for the root inside the inorder window.
        int mid = left;
        while (inorder[mid] != value) mid++;

        TreeNode root = new TreeNode(value);

        // Postorder is processed backwards: build the right subtree first.
        root.right = build(inorder, postorder, mid + 1, right, postIndex);
        root.left = build(inorder, postorder, left, mid - 1, postIndex);
        return root;
    }
}

