    public void flattenBrute(TreeNode root) {
        List<TreeNode> order = new ArrayList<>();
        collect(root, order);

        for (int i = 0; i < order.size() - 1; i++) {
            order.get(i).left = null;
            order.get(i).right = order.get(i + 1);
        }

        if (!order.isEmpty()) {
            order.get(order.size() - 1).left = null;
            order.get(order.size() - 1).right = null;
        }
    }

    private void collect(TreeNode root, List<TreeNode> order) {
        if (root == null) return;
        order.add(root);
        collect(root.left, order);
        collect(root.right, order);
    }
}

