                }
            }
        var dirs = new int[][] { new[] { 1, 0 }, new[] { -1, 0 }, new[] { 0, 1 }, new[] { 0, -1 } };
        while (queue.Count > 0) {
            var cell = queue.Dequeue();
            foreach (var d in dirs) {
                int x = cell[0] + d[0], y = cell[1] + d[1];
                if (x >= 0 && x < m && y >= 0 && y < n && dist[x][y] == -1) {
                    dist[x][y] = dist[cell[0]][cell[1]] + 1;
                    queue.Enqueue(new[] { x, y });
                }
            }
        }
        return dist;
    }
}

