class Solution {
    List<List<String>> findLadders(String begin, String end, List<String> words) {
        Set<String> dict = new HashSet<>(words);
        Map<String, List<String>> parent = new HashMap<>();
        Queue<String> q = new ArrayDeque<>(); q.offer(begin);
        Set<String> seen = new HashSet<>(); seen.add(begin); boolean found = false;
        while (!q.isEmpty() && !found) {
            int size = q.size(); Set<String> level = new HashSet<>();
            while (size-- > 0) { String w = q.poll(); char[] a = w.toCharArray();
                for (int i = 0; i < a.length; i++) { char old = a[i];
                    for (char ch = 'a'; ch <= 'z'; ch++) { a[i] = ch; String n = new String(a);
                        if (!dict.contains(n) || seen.contains(n)) continue;
                        if (level.add(n)) q.offer(n);
                        parent.computeIfAbsent(n, k -> new ArrayList<>()).add(w);
                        if (n.equals(end)) found = true;
                    } a[i] = old;
                }
            } seen.addAll(level);
        }
        List<List<String>> ans = new ArrayList<>(); if (!seen.contains(end)) return ans;
        build(end, begin, parent, new ArrayList<>(), ans); return ans;
    }
    void build(String word, String begin, Map<String,List<String>> p, List<String> path, List<List<String>> ans) {
        path.add(word); if (word.equals(begin)) { List<String> x = new ArrayList<>(path); Collections.reverse(x); ans.add(x); }
        else for (String prev : p.getOrDefault(word, List.of())) build(prev, begin, p, path, ans);
        path.remove(path.size() - 1);
    }
}

