        for (int i = 0; i < n; i++) adj.Add(new List<int[]>());
        foreach (var e in edges) {
            adj[e[0]].Add(new[] { e[1], e[2] });
            adj[e[1]].Add(new[] { e[0], e[2] });
        }
        var inMst = new bool[n];
        var pq = new PriorityQueue<int, int>();
        pq.Enqueue(0, 0);
        int total = 0;
        while (pq.Count > 0) {
            pq.TryDequeue(out int node, out int w);
            if (inMst[node]) continue;
            inMst[node] = true;
            total += w;
            foreach (var edge in adj[node])
                if (!inMst[edge[0]]) pq.Enqueue(edge[0], edge[1]);
        }
        return total;
    }
}

