class Solution {
    int[] parent;

    List<List<String>> accountsMerge(List<List<String>> accounts) {
        int n = accounts.size();
        parent = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        Map<String, Integer> owner = new HashMap<>();
        for (int i = 0; i < n; i++) {
            List<String> account = accounts.get(i);
            for (int j = 1; j < account.size(); j++) {
                String email = account.get(j);
                if (owner.containsKey(email)) {
                    int ra = find(i), rb = find(owner.get(email));
                    if (ra != rb) parent[ra] = rb;
                } else {
                    owner.put(email, i);
                }
            }
        }
        Map<Integer, List<String>> merged = new HashMap<>();
        for (Map.Entry<String, Integer> e : owner.entrySet()) {
            int root = find(e.getValue());
            merged.computeIfAbsent(root, k -> new ArrayList<>()).add(e.getKey());
        }
        List<List<String>> res = new ArrayList<>();
        for (Map.Entry<Integer, List<String>> e : merged.entrySet()) {
            List<String> group = e.getValue();
            Collections.sort(group);
            group.add(0, accounts.get(e.getKey()).get(0));
            res.add(group);
        }
        return res;
    }

    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
