public class Solution {
    public int Kosaraju(int n, int[][] edges) {
        var adj = new List<List<int>>();
        var rev = new List<List<int>>();
        for (int i = 0; i < n; i++) {
            adj.Add(new List<int>());
            rev.Add(new List<int>());
        }
        foreach (var e in edges) {
            adj[e[0]].Add(e[1]);
            rev[e[1]].Add(e[0]);
        }
        var visited = new bool[n];
        var stack = new Stack<int>();
        for (int i = 0; i < n; i++)
            if (!visited[i]) Order(i, adj, visited, stack);
        var seen = new bool[n];
        int count = 0;
        while (stack.Count > 0) {
            int node = stack.Pop();
            if (!seen[node]) {
                count++;
                Walk(node, rev, seen);
            }
        }
        return count;
    }

    private void Order(int node, List<List<int>> adj, bool[] visited, Stack<int> stack) {
        visited[node] = true;
        foreach (int next in adj[node])
            if (!visited[next]) Order(next, adj, visited, stack);
        stack.Push(node);
    }

    private void Walk(int node, List<List<int>> rev, bool[] seen) {
        seen[node] = true;
        foreach (int next in rev[node])
            if (!seen[next]) Walk(next, rev, seen);
    }
}

