class Solution {
    public int minFallingPathSum(int[][] matrix) {
        int n = matrix.length;
        Integer[][] memo = new Integer[n][n];
        int best = Integer.MAX_VALUE;
        for (int c = 0; c < n; c++) best = Math.min(best, path(matrix, n - 1, c, memo));
        return best;
    }
    private int path(int[][] matrix, int r, int c, Integer[][] memo) {
        if (c < 0 || c >= matrix.length) return Integer.MAX_VALUE / 2;
        if (r == 0) return matrix[0][c];
        if (memo[r][c] != null) return memo[r][c];
        int top = Math.min(path(matrix, r - 1, c - 1, memo), path(matrix, r - 1, c, memo));
        top = Math.min(top, path(matrix, r - 1, c + 1, memo));
        return memo[r][c] = matrix[r][c] + top;
    }
}

