    public int maximumChocolates(int r, int c, int[][] grid) {
        Integer[][][] memo = new Integer[r][c][c];
        return collect(grid, 0, 0, c - 1, memo);
    }
    private int collect(int[][] grid, int row, int col1, int col2, Integer[][][] memo) {
        int cols = grid[0].length;
        if (col1 < 0 || col1 >= cols || col2 < 0 || col2 >= cols) return Integer.MIN_VALUE / 2;
        if (row == grid.length - 1) return grid[row][col1] + (col1 == col2 ? 0 : grid[row][col2]);
        if (memo[row][col1][col2] != null) return memo[row][col1][col2];
        int best = Integer.MIN_VALUE;
        for (int d1 = -1; d1 <= 1; d1++) {
            for (int d2 = -1; d2 <= 1; d2++) {
                best = Math.max(best, collect(grid, row + 1, col1 + d1, col2 + d2, memo));
            }
        }
        int here = grid[row][col1] + (col1 == col2 ? 0 : grid[row][col2]);
        return memo[row][col1][col2] = here + best;
    }
}

