        return solve(s, t, 0, 0);
    }

    int solve(String s, String t, int i, int j) {
        if (i == s.length()) return t.length() - j;
        if (j == t.length()) return s.length() - i;
        if (memo[i][j] != null) return memo[i][j];
        if (s.charAt(i) == t.charAt(j)) return memo[i][j] = solve(s, t, i + 1, j + 1);
        int res = 1 + Math.min(solve(s, t, i + 1, j), Math.min(solve(s, t, i, j + 1), solve(s, t, i + 1, j + 1)));
        return memo[i][j] = res;
    }
}

