        int n = arr.length;
        if (n == 0) return 0;
        int[] inc = new int[n], dec = new int[n];
        for (int i = 0; i < n; i++) {
            inc[i] = 1;
            for (int j = 0; j < i; j++)
                if (arr[j] < arr[i]) inc[i] = Math.max(inc[i], inc[j] + 1);
        }
        for (int i = n - 1; i >= 0; i--) {
            dec[i] = 1;
            for (int j = i + 1; j < n; j++)
                if (arr[j] < arr[i]) dec[i] = Math.max(dec[i], dec[j] + 1);
        }
        int best = 0;
        for (int i = 0; i < n; i++) best = Math.max(best, inc[i] + dec[i] - 1);
        return best;
    }
}

