class Solution {
    public int countWays(String exp) {
        int n = exp.length();
        long MOD = 1_000_000_007L;
        long[][] trueWays = new long[n][n];
        long[][] falseWays = new long[n][n];
        for (int i = 0; i < n; i += 2) {
            trueWays[i][i] = exp.charAt(i) == 'T' ? 1 : 0;
            falseWays[i][i] = exp.charAt(i) == 'F' ? 1 : 0;
        }
        for (int len = 3; len <= n; len += 2) {
            for (int left = 0; left + len <= n; left += 2) {
                int right = left + len - 1;
                for (int split = left + 1; split < right; split += 2) {
                    long lt = trueWays[left][split - 1];
                    long lf = falseWays[left][split - 1];
                    long rt = trueWays[split + 1][right];
                    long rf = falseWays[split + 1][right];
                    char op = exp.charAt(split);
                    long total = (lt + lf) * (rt + rf) % MOD;
                    long t = 0;
                    if (op == '&') {
                        t = lt * rt % MOD;
                    } else if (op == '|') {
                        t = (total - lf * rf % MOD + MOD) % MOD;
                    } else {
                        t = (lt * rf + lf * rt) % MOD;
                    }
                    trueWays[left][right] = (trueWays[left][right] + t) % MOD;
                    falseWays[left][right] = (falseWays[left][right] + total - t + MOD) % MOD;
                }
            }
        }
        return (int) trueWays[0][n - 1];
    }
}

