            for (int j = i; j < n; j++) {
                if (s[i] == s[j] && (j - i < 2 || pal[i + 1, j - 1])) {
                    pal[i, j] = true;
                    cuts[i] = Math.Min(cuts[i], j == n - 1 ? 0 : 1 + cuts[j + 1]);
                }
            }
        }
        return cuts[0];
    }
}

