class Solution {
    public int minReversals(String s) {
        int n = s.length();
        if (n % 2 != 0) return -1;
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (c == '{') stack.push(c);
            else if (!stack.isEmpty() && stack.peek() == '{') stack.pop();
            else stack.push(c);
        }
        int open = 0, close = 0;
        while (!stack.isEmpty()) {
            if (stack.pop() == '{') open++;
            else close++;
        }
        return (open + 1) / 2 + (close + 1) / 2;
    }
}

