class Solution {
    public int search(String text, String pattern) {
        int n = text.length(), m = pattern.length();
        if (m > n) return -1;
        long base = 31, mod = 1_000_000_007L;
        long patternHash = 0, windowHash = 0, highestPower = 1;
        for (int i = 0; i < m - 1; i++) highestPower = highestPower * base % mod;
        for (int i = 0; i < m; i++) {
            patternHash = (patternHash * base + pattern.charAt(i)) % mod;
            windowHash = (windowHash * base + text.charAt(i)) % mod;
        }
        for (int i = 0; i + m <= n; i++) {
            if (patternHash == windowHash && matches(text, pattern, i)) return i;
            if (i + m < n)
                windowHash = ((windowHash - text.charAt(i) * highestPower % mod + mod) * base
                        + text.charAt(i + m)) % mod;
        }
        return -1;
    }

    private boolean matches(String text, String pattern, int start) {
        for (int j = 0; j < pattern.length(); j++)
            if (text.charAt(start + j) != pattern.charAt(j)) return false;
        return true;
    }
}

