class Solution {
    public String longestHappyPrefix(String s) {
        int n = s.length();
        long base = 31, mod = 1_000_000_007L;
        long prefixHash = 0, suffixHash = 0, power = 1;
        int best = 0;
        for (int len = 1; len < n; len++) {
            prefixHash = (prefixHash * base + s.charAt(len - 1)) % mod;
            suffixHash = (s.charAt(n - len) * power + suffixHash) % mod;
            if (prefixHash == suffixHash) best = len;
            power = power * base % mod;
        }
        return s.substring(0, best);
    }
}

