public class Solution {
    private long?[,] memo;

    public long CountPalindromicSubsequences(string s) {
        int n = s.Length;
        memo = new long?[n, n];
        return Solve(s, 0, n - 1);
    }

    private long Solve(string s, int i, int j) {
        if (i > j) return 0;
        if (i == j) return 1;
        if (memo[i, j].HasValue) return memo[i, j].Value;
        long result;
        if (s[i] == s[j])
            result = Solve(s, i + 1, j) + Solve(s, i, j - 1) + 1;
        else
            result = Solve(s, i + 1, j) + Solve(s, i, j - 1) - Solve(s, i + 1, j - 1);
        memo[i, j] = result;
        return result;
    }
}

